sys_ux_client_script.script:
function handler({api, event, helpers, imports}) {

    // Capture the exact moment BUZZ is pressed.
    // Epoch milliseconds are timezone-independent.
    var buzzerTime = Date.now();

    console.log("=================================");
    console.log("QUIZPULSE BUZZ PRESSED");
    console.log("Buzzer Time (epoch ms):", buzzerTime);
    console.log("Buzzer Time (local):", new Date(buzzerTime).toString());
    console.log("=================================");

    // Store timestamp in client state
    api.setState("buzzerTime", String(buzzerTime));

    // Get current Quiz Session
    var sessionResults =
        api.data.look_up_multiple_records_2.results;

    // Get current Participant
    var participantResults =
        api.data.look_up_multiple_records_1.results;

    // Validate Quiz Session
    if (!sessionResults || sessionResults.length === 0) {
        console.error("QuizPulse: Quiz Session not found.");
        return;
    }

    // Validate Participant
    if (!participantResults || participantResults.length === 0) {
        console.error("QuizPulse: Participant not found.");
        return;
    }

    // Get Quiz Session sys_id
    var quizSessionId =
        sessionResults[0]._row_data.uniqueValue;

    // Get Participant sys_id
    var participantId =
        participantResults[0]._row_data.uniqueValue;

    console.log("Quiz Session ID:", quizSessionId);
    console.log("Participant ID:", participantId);

    // Execute the Transform Data Resource
    api.data.quizpulse___create_buzzer_response_1.execute({
        quizSessionId: quizSessionId,
        participantId: participantId,
        buzzerTime: String(buzzerTime),
        runNumber: "1"
    });

    console.log("QuizPulse: Buzzer Response Transform executed.");
}
